       now() - make_interval(mins => v.minutes_ago), now()
FROM (
VALUES
  ('puma', 'zapatillas-running', 'Zapatillas Running Mujer Electrify Nitro 3', 'puma-zapatillas-running-mujer-electrify-nitro-3-verde', 'Zapatillas Running Mujer Electrify Nitro 3 de Puma, con amortiguación para correr en pista o en la ciudad. Suela de caucho antideslizante con buen agarre. Costuras reforzadas para mayor durabilidad. Color: Verde.', 0),
