  ('puma', 'zapatillas-de-futbol', 'Zapatillas de Fútbol Hombre Future 7 Play', 'puma-zapatillas-de-futbol-hombre-future-7-play-azul', 'Zapatillas de Fútbol Hombre Future 7 Play de Puma, para canchas sintéticas con tapones de goma. Capellada de material sintético fácil de limpiar. Suela de caucho antideslizante con buen agarre. Color: Azul.', 475),
  ('walking', 'zapatillas-escolares', 'Zapatillas Escolares de Cuero Niña Brisa', 'walking-zapatillas-escolares-de-cuero-nina-brisa-negro', 'Zapatillas Escolares de Cuero Niña Brisa de Walking, resistentes para el uso escolar diario. Diseño ligero y flexible. Suela de caucho antideslizante con buen agarre. Color: Negro.', 476),
  ('bubba-bags', 'bolsos-y-morrales', 'Canguro Unisex Elena', 'bubba-bags-canguro-unisex-elena-beige', 'Canguro Unisex Elena de Bubba Bags, práctico para llevar lo esencial. Acabado resistente al uso diario. Correa ajustable para llevarlo como prefieras. Color: Beige.', 477),
  ('sundara-joyas', 'joyeria-y-accesorios', 'Set de Aretes SUN000892', 'sundara-joyas-set-de-aretes-sun000892-plata', 'Set de Aretes SUN000892 de Sundara Joyas, de acero inoxidable hipoalergénico. Ideal para regalar. Incluye empaque de la marca. Color: Plata.', 478),
  ('warner-bros', 'ropa-infantil', 'Polera Niño Batman', 'warner-bros-polera-nino-batman-celeste', 'Polera Niño Batman de Warner Bros, de algodón suave y estampados divertidos. Costuras reforzadas que mantienen la forma tras cada lavado. Corte cómodo que acompaña el movimiento. Color: Celeste.', 479),
  ('puma', 'calzado-infantil', 'Zapatillas Urbanas Niña Courtflex V3', 'puma-zapatillas-urbanas-nina-courtflex-v3-rojo', 'Zapatillas Urbanas Niña Courtflex V3 de Puma, con cierre práctico para que los más pequeños se calcen solos. Capellada de material sintético fácil de limpiar. Diseño ligero y flexible. Color: Rojo.', 480),
  ('warner-bros', 'juguetes-y-juegos', 'Juego de Cartas Batman', 'warner-bros-juego-de-cartas-batman-multicolor', 'Juego de Cartas Batman de Warner Bros, para jugar en familia o con amigos. Estimula la creatividad y la imaginación. Materiales seguros y resistentes. Color: Multicolor.', 481),
  ('just4u', 'vestidos', 'Vestido Largo Estampado Mujer Milán', 'just4u-vestido-largo-estampado-mujer-milan-celeste', 'Vestido Largo Estampado Mujer Milán de Just4U, con caída fluida para el día o la noche. Corte cómodo que acompaña el movimiento. Costuras reforzadas que mantienen la forma tras cada lavado. Color: Celeste.', 482),
  ('adidas', 'calzado-infantil', 'Sandalias Niña Tensaur Run', 'adidas-sandalias-nina-tensaur-run-rojo', 'Sandalias Niña Tensaur Run de Adidas, con cierre práctico para que los más pequeños se calcen solos. Diseño ligero y flexible. Suela de caucho antideslizante con buen agarre. Color: Rojo.', 483),
  ('the-north-face', 'casacas', 'Casaca Acolchada Hombre Resolve 2', 'the-north-face-casaca-acolchada-hombre-resolve-2-gris', 'Casaca Acolchada Hombre Resolve 2 de The North Face, que protege del viento y del frío. Corte cómodo que acompaña el movimiento. Lavar a máquina con colores similares. Color: Gris.', 484),
  ('nike', 'ropa-infantil', 'Conjunto Niña Sportswear Kids', 'nike-conjunto-nina-sportswear-kids-amarillo', 'Conjunto Niña Sportswear Kids de Nike, de algodón suave y estampados divertidos. Tela suave al tacto y de secado rápido. Fácil de combinar con el resto de tu clóset. Color: Amarillo.', 485),
  ('beira-rio', 'botas-y-botines', 'Botín Mujer 4109.038', 'beira-rio-botin-mujer-4109-038-plata', 'Botín Mujer 4109.038 de Beira Rio, con caña media que abriga y estiliza. Forro textil transpirable. Diseño ligero y flexible. Color: Plata.', 486),
  ('bubba-bags', 'mochilas', 'Mochila Escolar Mujer Coral', 'bubba-bags-mochila-escolar-mujer-coral-rosado', 'Mochila Escolar Mujer Coral de Bubba Bags, con espaldar acolchado y varios compartimentos. Acabado resistente al uso diario. Correa ajustable para llevarlo como prefieras. Color: Rosado.', 487),
  ('just4u', 'blusas', 'Blusa Casual Mujer Elena', 'just4u-blusa-casual-mujer-elena-coral', 'Blusa Casual Mujer Elena de Just4U, de tela ligera y corte femenino. Tela suave al tacto y de secado rápido. Costuras reforzadas que mantienen la forma tras cada lavado. Color: Coral.', 488),
  ('kansas', 'casacas', 'Casaca Cortavientos Hombre Marco', 'kansas-casaca-cortavientos-hombre-marco-marron', 'Casaca Cortavientos Hombre Marco de Kansas, que protege del viento y del frío. Lavar a máquina con colores similares. Tela suave al tacto y de secado rápido. Color: Marrón.', 489),
  ('skechers', 'calzado-infantil', 'Zapatillas Kids Niña Twinkle Toes', 'skechers-zapatillas-kids-nina-twinkle-toes-azul', 'Zapatillas Kids Niña Twinkle Toes de Skechers, con cierre práctico para que los más pequeños se calcen solos. Diseño ligero y flexible. Capellada de material sintético fácil de limpiar. Color: Azul.', 490),
  ('tuhome', 'decoracion', 'Cojín Decorativo Enzo', 'tuhome-cojin-decorativo-enzo-verde', 'Cojín Decorativo Enzo de Tuhome, para darle un toque cálido a tus espacios. Combina con distintos estilos de decoración. Fácil de limpiar. Color: Verde.', 491),
  ('bubba-bags', 'equipaje', 'Maleta de Cabina 20" Originals Matte', 'bubba-bags-maleta-de-cabina-20-originals-matte-negro', 'Maleta de Cabina 20" Originals Matte de Bubba Bags, resistente para tus viajes. Liviana y fácil de maniobrar. Ruedas de giro 360° y asa telescópica. Color: Negro.', 492),
  ('limoni', 'joyeria-y-accesorios', 'Pulsera Delta', 'limoni-pulsera-delta-dorado', 'Pulsera Delta de Limoni, de acero inoxidable hipoalergénico. Ideal para regalar. Incluye empaque de la marca. Color: Dorado.', 493),
  ('platanitos', 'pantuflas', 'Pantufla Unisex P Celeste', 'platanitos-pantufla-unisex-p-celeste-beige', 'Pantufla Unisex P Celeste de Platanitos, suaves y abrigadoras para estar en casa. Costuras reforzadas para mayor durabilidad. Forro textil transpirable. Color: Beige.', 494),
  ('speedo', 'ropa-de-bano', 'Traje de Baño Entero Mujer Dive Jammer', 'speedo-traje-de-bano-entero-mujer-dive-jammer-turquesa', 'Traje de Baño Entero Mujer Dive Jammer de Speedo, de secado rápido y resistente al cloro. Fácil de combinar con el resto de tu clóset. Tela suave al tacto y de secado rápido. Color: Turquesa.', 495),
  ('under-armour', 'shorts', 'Short Training Hombre Tech Vent', 'under-armour-short-training-hombre-tech-vent-verde', 'Short Training Hombre Tech Vent de Under Armour, con pretina elástica y cordón ajustable. Costuras reforzadas que mantienen la forma tras cada lavado. Fácil de combinar con el resto de tu clóset. Color: Verde.', 496),
  ('tuhome', 'cocina-y-mesa', 'Taza de Cerámica Paracas', 'tuhome-taza-de-ceramica-paracas-verde', 'Taza de Cerámica Paracas de Tuhome, apto para microondas y lavavajillas. Fácil de limpiar. Producto con garantía de la marca. Color: Verde.', 497),
  ('aranni', 'sandalias', 'Sandalias Planas Dama Gala', 'aranni-sandalias-planas-dama-gala-beige', 'Sandalias Planas Dama Gala de Aranni, frescas y cómodas para la temporada de calor. Suela de caucho antideslizante con buen agarre. Diseño ligero y flexible. Color: Beige.', 498),
  ('reebok', 'zapatillas-running', 'Zapatillas Running Hombre Floatride Energy 5', 'reebok-zapatillas-running-hombre-floatride-energy-5-naranja', 'Zapatillas Running Hombre Floatride Energy 5 de Reebok, con amortiguación para correr en pista o en la ciudad. Plantilla acolchada que brinda comodidad durante todo el día. Suela de caucho antideslizante con buen agarre. Color: Naranja.', 499)
) AS v(brand_slug, category_slug, name, slug, description, minutes_ago)
JOIN "Brand" b ON b."slug" = v.brand_slug
JOIN "Category" c ON c."slug" = v.category_slug
ON CONFLICT ("slug") DO UPDATE
  SET "name" = EXCLUDED."name",
      "description" = EXCLUDED."description",
      "brandId" = EXCLUDED."brandId",
      "categoryId" = EXCLUDED."categoryId",
      "isActive" = true,
      "createdAt" = EXCLUDED."createdAt",
      "updatedAt" = now();

