) AS v(slug, sku, size_system, size_value, color, price, compare_price, stock)
JOIN "Product" p ON p."slug" = v.slug
ON CONFLICT ("sku") DO UPDATE
  SET "productId" = EXCLUDED."productId",
      "sizeSystem" = EXCLUDED."sizeSystem",
      "sizeValue" = EXCLUDED."sizeValue",
      "color" = EXCLUDED."color",
      "price" = EXCLUDED."price",
      "comparePrice" = EXCLUDED."comparePrice",
      "stock" = EXCLUDED."stock",
      "isActive" = true,
      "updatedAt" = now();

-- Limpieza: desactiva variantes y productos del catálogo (SKU PLT-…) que ya no
-- se generan y borra sus imágenes sobrantes. No toca los datos del seed original.
UPDATE "ProductVariant" SET "isActive" = false, "updatedAt" = now()
WHERE "sku" LIKE 'PLT-%' AND "isActive" AND "updatedAt" <> now()::timestamp(3);

UPDATE "Product" p SET "isActive" = false, "updatedAt" = now()
WHERE p."isActive" AND p."updatedAt" <> now()::timestamp(3)
  AND EXISTS (SELECT 1 FROM "ProductVariant" cv WHERE cv."productId" = p."id" AND cv."sku" LIKE 'PLT-%')
  AND NOT EXISTS (SELECT 1 FROM "ProductVariant" ov WHERE ov."productId" = p."id" AND ov."sku" NOT LIKE 'PLT-%');

DELETE FROM "ProductImage" i
WHERE i."createdAt" <> now()::timestamp(3)
  AND EXISTS (SELECT 1 FROM "ProductVariant" cv WHERE cv."productId" = i."productId" AND cv."sku" LIKE 'PLT-%')
  AND NOT EXISTS (SELECT 1 FROM "ProductVariant" ov WHERE ov."productId" = i."productId" AND ov."sku" NOT LIKE 'PLT-%');

COMMIT;
